SELECT target_ids.target_user_id AS targetUserId, CASE WHEN ub.blocked_user_id IS NOT NULL THEN true ELSE false END AS isBlocked FROM (
SELECT #{id} AS target_user_id
) AS target_ids LEFT JOIN user_block ub ON ub.blocked_user_id = target_ids.target_user_id AND ub.user_id = #{userId}
